"""Recover TableSM1 without converting non-detects, blanks, or food species."""
import collections,datetime,hashlib,json,pathlib,statistics
from docx import Document
b=pathlib.Path('data/evidence/contracts/leafy-greens');p=b/'retrieval/hossain2016-TableS1.docx';sha=hashlib.sha256(p.read_bytes()).hexdigest()
i=next(x for x in json.load(open(b/'access-inventory.json'))['items'] if x['source_id'].startswith('hossain2016'));d=Document(p)
table=d.tables[0];allrows=[];records=[];district='';district_id='';thana=''
names={'2':('Green cabbage','Brassica oleracea capitata var. alba'),'3':('Red spinach','Amaranthus dubius')}
for rn,row in enumerate(table.rows[2:],3):
 cells=[c.text.strip() for c in row.cells]
 if not cells[2].isdigit():continue
 if cells[1]:district=cells[1];district_id=cells[0];thana=cells[4]
 elif cells[4]:thana=cells[4]
 allrows.append({'table_row':rn,'district_id':district_id,'district':district,'thana_expression_verbatim':thana,'cells':cells})
 if cells[3] not in names:continue
 name,species=names[cells[3]]
 for analyte,column in [('Pb',5),('Cr',8),('Cd',11)]:
  text=cells[column];isnd=text in ['ND','ND*'];missing=text in ['-',''];value=None if isnd or missing else float(text)
  records.append({'id':f'lg-full-hossain-SM1-{cells[2]}-{analyte}','source_id':i['source_id'],'family_id':'hossain-bangladesh-64-district-surveillance','analyte':analyte,'material':name,'species':species,'form':'unpeeled, tap-water then distilled-water washed; oven-dried80°C to stable mass','basis':'Dry weight','origin_or_market':district+', Bangladesh; collection source '+thana,'year':'Collection year not specified; national-holiday sampling before2016 publication','statistic':'individual sample concentration' if value is not None else 'individual sample non-detect' if isnd else 'sample analyte result missing','n':1,'n_note':'One vegetable sample per type per sampled district/thana; no analytical replicates accommodated. Districts and crops belong to one surveillance family.','sample_unit':'individual collected vegetable sample; market/field acquisition context unspecified','unit_original':'µg/g DW','unit':'µg/kg','value_original':value,'value':value*1000 if value is not None else None,'lower_bound':0 if isnd else None,'upper_bound':None,'reported_text':text,'censoring':'ND at unspecified ppb instrumental level for0.2g dry sample in100ml; food-basis numeric bound unavailable; not zero' if isnd else 'Dash indicates missing result, not a non-detect' if missing else 'Reported detected result','locator':{'artifact':str(p),'sha256':sha,'kind':'cell','location':f'TableSM1, OOXMLtable1 row{rn} column{column+1}, sample serial{cells[2]}, {analyte}'},'scientific_fit_status':'leafy-food sample; preserve cabbage and Amaranthus species separately'})
assert len(allrows)==292 and len(set(x['cells'][2] for x in allrows))==292
assert len(records)==330
checks=[]
printed={('2','Pb'):(5.9505,12.6865,.002,29.794,37,49),('3','Pb'):(6.799,13.79,.049,38.439,35,61),('2','Cr'):(1.1665,2.1363,None,None,41,49),('3','Cr'):(.288,3.593,None,None,58,61),('2','Cd'):(.436,.64,.098,1.11,32,49),('3','Cd'):(.885,1.765,.05,5.323,27,60)}
summaries=[]
for (vegetable,analyte),(median,q3,minimum,maximum,nd,n) in printed.items():
 name,species=names[vegetable];raw=[r for r in records if r['material']==name and r['analyte']==analyte];values=[r['value_original'] for r in raw if r['value_original'] is not None];observed=statistics.median(values)
 assert abs(observed-median)<1e-9 and sum(r['reported_text'].startswith('ND') for r in raw)==nd
 checks.append({'material':name,'analyte':analyte,'analysed_n':n,'non_detect_n':nd,'detected_n':len(values),'median_of_detected_values_recomputed':observed,'printed_median':median,'finding':'Printed median is the detected subset only, not all analysed samples.'})
 for statistic,value in [('median among detections only',median),('upper quartile among detections only',q3),('minimum detected concentration',minimum),('maximum detected concentration',maximum)]:
  if value is None:continue
  page=7 if analyte=='Cr' else 8 if analyte=='Cd' else 9
  summaries.append({'id':f'lg-full-hossain-Table{page-4}-{vegetable}-{analyte}-{statistic.split()[0]}','source_id':i['source_id'],'family_id':'hossain-bangladesh-64-district-surveillance','analyte':analyte,'material':name,'species':species,'form':'washed, oven-dried vegetable','basis':'Dry weight','origin_or_market':'Bangladesh,64-district surveillance','year':'Collection year unreported; published2016','statistic':statistic,'n':len(values),'n_note':f'Statistic uses{len(values)} detected results, excluding{nd} ND among{n} analysed samples. Raw sample records, including missing results, retained separately.','sample_unit':'detected subset of individual vegetable samples','unit_original':'µg/g DW','unit':'µg/kg','value_original':value,'value':value*1000,'censoring':'Non-detects excluded from source descriptive statistics; these conditional medians are not full-subgroup medians and are not automatic HMI reference units.','locator':{'artifact':i['artifact']['path'],'sha256':i['artifact']['sha256'],'kind':'cell','location':f'PDFp{page}, Table{page-4}, {name}, {statistic}'},'reference_role':'Do not duplicate raw samples or admit a detection-conditional median as an all-sample median.'})
records+=summaries;assert len(summaries)==20
(b/'hossain-supporting-table-raw.json').write_text(json.dumps({'artifact':str(p),'sha256':sha,'rows':allrows,'vegetable_key':{'1':'White potato','2':'Green cabbage','3':'Red spinach (Amaranthus dubius)','4':'White radish','5':'Green bean'},'note':'All292 rows retained, all64 district labels and thana expressions preserved. Thana expressions such as2=X;3,5=Y are not silently assigned to the wrong vegetable. Nonleaf food types are outside leafy-food occurrence.'},indent=2)+'\n')
(b/'recovered-hossain-results.json').write_text(json.dumps({'records':records,'counts':{'leaf_samples':110,'sample_analyte_cells':330,'missing_analyte_cells':sum(r['reported_text']=='-' for r in records if 'reported_text' in r),'source_detected_subset_statistics':20},'summary_integrity_checks':checks},indent=2)+'\n')
(b/'primary-review-hossain.json').write_text(json.dumps({'source_id':i['source_id'],'reviewed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'identity_verified':True,'completeness_verified':True,'artifact':i['artifact'],'supporting_artifact':{'path':str(p),'sha256':sha},'identity_proof':'Complete14-page SpringerPlus primary PDF and publisher-linked12-page supporting Word table. Supplement title, full author list, affiliations and TableSM1 descriptions match article DOI10.1186/s40064-016-3458-9. All292 unique sample serials are present and type counts match articleTables3–5.','decision':'occurrence_extracted','extraction_complete':True,'result_ids':[r['id'] for r in records],'limits':'All330 sample-analyte cells from49 cabbage+61 red-spinach samples retained, including one missing red-spinach Cd value.20 source subgroup descriptive statistics extracted separately. Recomputed medians prove detection-conditional source denominators. Numeric ND thresholds unavailable; no zero or half-LOD substitution. Source fresh-weight exposure and standards conversions use generic published moisture values, not measured sample moisture, so not adopted as new observed FW concentrations. TotalCr remains totalCr; source comparisons toCrVI RfD do not establishCrVI measurement or safety. Mixed-five-vegetable overall statistics, contaminant status labels and geographic exceedance counts remain contextual analysis, not additional concentration samples.'},indent=2)+'\n')
print('Hossain:330 sample-analyte cells+20 detected-subset summary statistics; all292 supporting rows retained')
